(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.3)*18+Math.cos(y*0.013-t*0.2)*12+Math.sin((x+y)*0.01+t*0.15)*8;
  const w1y = Math.cos(y*0.018-t*0.25)*18+Math.sin(x*0.015+t*0.35)*12+Math.cos((x-y)*0.012-t*0.18)*8;
  const mx = x+w1x, my = y+w1y;
  const w2x = Math.sin(mx*0.025-t*0.4)*10+Math.cos(my*0.02+t*0.3)*7;
  const w2y = Math.cos(my*0.022+t*0.35)*10+Math.sin(mx*0.018-t*0.28)*7;
  const sx = mx+w2x, sy = my+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100+Math.sin(t*1.2)*30, 80+Math.cos(t*0.4)*50+Math.cos(t*0.9)*20, 0.08, 2.0, 1.0],
    [320+Math.cos(t*0.5)*100+Math.cos(t*1.1)*25, 160+Math.sin(t*0.7)*50+Math.sin(t*1.3)*15, 0.1, 1.7, 0.9],
    [240+Math.sin(t*0.3+2)*140+Math.sin(t*0.8)*20, 120+Math.cos(t*0.5+1)*90+Math.cos(t*1.0)*25, 0.06, 2.3, 1.1],
    [120+Math.cos(t*0.8+1)*80+Math.sin(t*1.5)*15, 180+Math.sin(t*0.6+3)*60+Math.cos(t*1.2)*20, 0.12, 1.5, 0.8],
    [360+Math.sin(t*0.4+4)*90+Math.cos(t*0.7)*20, 60+Math.cos(t*0.9+2)*70+Math.sin(t*1.4)*15, 0.07, 2.6, 1.2],
    [240+Math.cos(t*0.35+5)*120+Math.sin(t*0.6)*25, 200+Math.sin(t*0.55)*80+Math.cos(t*0.8)*20, 0.09, 1.9, 0.95],
    [80+Math.sin(t*0.45+3)*60, 40+Math.cos(t*0.65+2)*40, 0.14, 1.3, 0.7],
    [400+Math.cos(t*0.55+1)*70, 200+Math.sin(t*0.75+4)*50, 0.11, 1.8, 1.05]
  ];
  let aS=0, iS=0, wS=0;
  for(const[sX,sY,f,sp,w]of src){const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);aS+=Math.sin(d*f-t*sp)*w;iS+=Math.sin(d*f*0.7+t*sp*0.6+1.5)*w;wS+=w;}
  const act=aS/wS, inh=iS/wS;
  const bg1=(Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2;
  const bg2=Math.sin((sx+sy)*0.12+t*2.5)*0.2+Math.sin((sx-sy)*0.1-t*2)*0.2;
  const bg3=Math.sin(sx*0.08+Math.sin(sy*0.06+t)*2+t*1.5)*0.15+Math.cos(sy*0.07+Math.cos(sx*0.05-t)*2-t*1.3)*0.15;
  const bg=bg1+bg2+bg3;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2), ang=Math.atan2(sy-cy,sx-cx);
  const spiral=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.4;
  const radial=Math.sin(dist*0.08-t*2)*Math.cos(ang*2+Math.sin(dist*0.03+t)*2)*0.2;
  let rings=0;
  for(let i=0;i<3;i++){const rcx=cx+Math.cos(t*0.3+i*2.1)*100,rcy=cy+Math.sin(t*0.4+i*1.7)*60;const rd=Math.sqrt((sx-rcx)**2+(sy-rcy)**2);rings+=Math.sin(rd*0.1-t*2.5+i)*0.15;}
  const cell=Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5+Math.sin(sx*0.2-sy*0.12+t*0.7)*0.3)*1.5)*0.3;
  const reaction=Math.tanh((act-inh*0.7+bg*0.3+spiral+radial+rings)*2.2);
  const blend=reaction*0.7+cell*0.3, v=blend*0.5+0.5;
  const pal=[[5,12,45],[10,45,85],[15,90,120],[20,150,145],[45,195,165],[180,210,130],[240,195,80],[230,140,75],[195,85,85],[130,45,75],[60,20,55],[20,15,50],[5,12,45]];
  const idx=v*(pal.length-1), i=Math.min(idx|0,pal.length-2), f=idx-i;
  const lum=0.75+Math.sin(reaction*Math.PI)*0.25;
  const glow=Math.max(0,reaction-0.5)*2.0;
  const edge=Math.abs(reaction)>0.65?1.2:1.0;
  const vig=1.0-Math.pow(dist/280,2)*0.25;
  const br=(lum+glow*0.3)*edge*vig;
  return[
    Math.min(255,(pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*br+glow*15)|0,
    Math.min(255,(pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*br+glow*25)|0,
    Math.min(255,(pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*br+glow*35)|0
  ];
}
